import{_ as a,o as i,c as n,a3 as e}from"./chunks/framework.6_aCw6yF.js";const k=JSON.parse('{"title":"1Panel 面板安装与初体验","description":"在 Linux 上部署 1Panel 开源运维面板，从一键安装到日常使用的一次完整记录。","frontmatter":{"title":"1Panel 面板安装与初体验","description":"在 Linux 上部署 1Panel 开源运维面板，从一键安装到日常使用的一次完整记录。","date":"2026-11-14T00:00:00.000Z","category":"工善利器","subCategory":"服务器运维","tags":["Linux","1Panel","运维"],"author":"闲生"},"headers":[],"relativePath":"posts/tools/server/1panel.md","filePath":"posts/tools/server/1panel.md"}'),p={name:"posts/tools/server/1panel.md"};function l(t,s,h,r,c,d){return i(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="_1panel-面板安装与初体验" tabindex="-1">1Panel 面板安装与初体验 <a class="header-anchor" href="#_1panel-面板安装与初体验" aria-label="Permalink to &quot;1Panel 面板安装与初体验&quot;">​</a></h1><p>命令行用久了，总有些操作更适合交给图形界面：看磁盘 IO、翻日志、管容器、传文件。1Panel 是这类需求里比较轻的一个选择，开源、基于容器、安装也简单。</p><h2 id="一、1panel-是什么" tabindex="-1">一、1Panel 是什么 <a class="header-anchor" href="#一、1panel-是什么" aria-label="Permalink to &quot;一、1Panel 是什么&quot;">​</a></h2><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/202407091541272.png" alt="1Panel"></p><p><a href="https://1panel.cn/" target="_blank" rel="noreferrer">1Panel</a> 是一个现代化、开源的 Linux 服务器运维管理面板。它把常用的主机管理能力收进一个 Web 界面，同时把应用安装交给容器来做。</p><p>它的几个特点：</p><ul><li><strong>高效管理</strong>：通过 Web 图形界面管理主机监控、文件、数据库与容器；</li><li><strong>快速建站</strong>：深度集成 WordPress、<a href="https://github.com/halo-dev/halo/" target="_blank" rel="noreferrer">Halo</a> 等开源建站程序，域名绑定与 SSL 证书配置一键完成；</li><li><strong>应用商店</strong>：精选上架各类开源工具，安装与升级都在面板内完成；</li><li><strong>安全可靠</strong>：基于容器部署应用，缩小漏洞暴露面，并提供防火墙与日志审计；</li><li><strong>一键备份</strong>：支持备份到各类云端存储，恢复也只需要点几下。</li></ul><h2 id="二、环境说明" tabindex="-1">二、环境说明 <a class="header-anchor" href="#二、环境说明" aria-label="Permalink to &quot;二、环境说明&quot;">​</a></h2><p>本文是在个人测试环境里完成的实践，生产环境请按需调整防火墙与安全组策略。目标很简单：</p><ol><li>在 Linux 系统中部署 1Panel 面板；</li><li>熟悉面板的日常使用方式；</li><li>掌握 <code>1pctl</code> 这个运维命令。</li></ol><p>开始前先处理两件容易被忽略的事。</p><h3 id="关闭防火墙或放行端口" tabindex="-1">关闭防火墙或放行端口 <a class="header-anchor" href="#关闭防火墙或放行端口" aria-label="Permalink to &quot;关闭防火墙或放行端口&quot;">​</a></h3><p>可以选择直接关闭防火墙：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">systemctl</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> stop</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> firewalld</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> &amp;&amp;</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> systemctl</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> disable</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> firewalld</span></span></code></pre></div><p>也可以只放行面板端口（下面以 <code>10086</code> 为例）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">firewall-cmd</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> --permanent</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> --add-port=10086/tcp</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">firewall-cmd</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> --reload</span></span></code></pre></div><p>如果用的是云服务器，别忘了在安全组里同样放行这个端口。</p><h3 id="关闭-selinux" tabindex="-1">关闭 SELinux <a class="header-anchor" href="#关闭-selinux" aria-label="Permalink to &quot;关闭 SELinux&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">sed</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -i</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;"> &#39;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">s/SELINUX=enforcing/SELINUX=disabled/</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&#39;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /etc/selinux/config</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">setenforce</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;"> 0</span></span></code></pre></div><p>第一条命令改的是下次开机的配置，第二条让当前会话立即生效。</p><h2 id="三、在线安装" tabindex="-1">三、在线安装 <a class="header-anchor" href="#三、在线安装" aria-label="Permalink to &quot;三、在线安装&quot;">​</a></h2><p>安装目录可以自定义，默认是 <code>/opt</code>。先建好目录：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">mkdir</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -p</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /path/1Panel</span></span></code></pre></div><p>然后按发行版选择对应的一键安装脚本：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># Ubuntu</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">curl</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -sSL</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> https://resource.fit2cloud.com/1panel/package/quick_start.sh</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -o</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> quick_start.sh</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> &amp;&amp;</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> sudo</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> bash</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> quick_start.sh</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># RedHat / CentOS</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">curl</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -sSL</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> https://resource.fit2cloud.com/1panel/package/quick_start.sh</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -o</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> quick_start.sh</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> &amp;&amp;</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> sh</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> quick_start.sh</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># Debian</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">curl</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -sSL</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> https://resource.fit2cloud.com/1panel/package/quick_start.sh</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -o</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> quick_start.sh</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> &amp;&amp;</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> bash</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> quick_start.sh</span></span></code></pre></div><p>脚本执行后会依次询问安装目录、面板端口、面板用户名与密码。端口和账号都可以自定义，也可以直接回车采用默认值。安装过程中的关键输出大致如下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>[1Panel Log]: ======================= 开始安装 =======================</span></span>
<span class="line"><span>设置 1Panel 安装目录（默认为/opt）：</span></span>
<span class="line"><span>[1Panel Log]: 您选择的安装路径为 /opt</span></span>
<span class="line"><span>[1Panel Log]: 检测到 Docker 已安装，跳过安装步骤</span></span>
<span class="line"><span>[1Panel Log]: 启动 Docker</span></span>
<span class="line"><span>[1Panel Log]: ... 在线安装 docker-compose</span></span>
<span class="line"><span>[1Panel Log]: docker-compose 安装成功</span></span>
<span class="line"><span>设置 1Panel 端口（默认为20904）：10086</span></span>
<span class="line"><span>[1Panel Log]: 您设置的端口为：10086</span></span>
<span class="line"><span>设置 1Panel 面板用户（默认为95feba06e2）：xjx</span></span>
<span class="line"><span>[1Panel Log]: 您设置的面板用户为：xjx</span></span>
<span class="line"><span>[1Panel Log]: 启动 1Panel 服务</span></span>
<span class="line"><span>[1Panel Log]: 1Panel 服务启动成功!</span></span>
<span class="line"><span>[1Panel Log]: 请用浏览器访问面板:</span></span>
<span class="line"><span>[1Panel Log]: 外网地址: http://&lt;你的服务器 IP&gt;:10086/&lt;安全入口&gt;</span></span>
<span class="line"><span>[1Panel Log]: 内网地址: http://&lt;你的内网 IP&gt;:10086/&lt;安全入口&gt;</span></span>
<span class="line"><span>[1Panel Log]: 面板用户: xjx</span></span>
<span class="line"><span>[1Panel Log]: 项目官网: https://1panel.cn</span></span></code></pre></div><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/202407091545426.png" alt="安装完成"></p><p>注意地址末尾那串随机字符，它是 1Panel 的安全入口，访问时不能省略。</p><h2 id="四、首次访问" tabindex="-1">四、首次访问 <a class="header-anchor" href="#四、首次访问" aria-label="Permalink to &quot;四、首次访问&quot;">​</a></h2><p>浏览器打开安装输出里的地址，先看到的是初始化页面。</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/202407091547837.png" alt="初始化页面"></p><p>用刚才设置的用户名和密码登录，就能进入首页。</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/202407091548216.png" alt="1Panel 首页"></p><h2 id="五、面板的日常使用" tabindex="-1">五、面板的日常使用 <a class="header-anchor" href="#五、面板的日常使用" aria-label="Permalink to &quot;五、面板的日常使用&quot;">​</a></h2><h3 id="服务器概览" tabindex="-1">服务器概览 <a class="header-anchor" href="#服务器概览" aria-label="Permalink to &quot;服务器概览&quot;">​</a></h3><p>首页能看到系统状态、磁盘 IO 与进程的实时监控，适合做一次快速体检。</p><p><img src="https://img-blog.csdnimg.cn/direct/d2f3a20cce0e422db6d89f1777c4a1c1.png" alt="服务器概览"></p><h3 id="应用商店" tabindex="-1">应用商店 <a class="header-anchor" href="#应用商店" aria-label="Permalink to &quot;应用商店&quot;">​</a></h3><p>应用商店里可以直接安装各种开源应用，省去了自己写 compose 文件的步骤。</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/202407091548968.png" alt="应用商店"></p><h3 id="容器管理" tabindex="-1">容器管理 <a class="header-anchor" href="#容器管理" aria-label="Permalink to &quot;容器管理&quot;">​</a></h3><p>宿主机的容器、镜像、编排、网络、存储卷、仓库以及 Docker 基础配置，都在这里统一管理。</p><p><img src="https://img-blog.csdnimg.cn/direct/1428ae7d030e462d9fcd59cfdca45d16.png" alt="容器管理"></p><h3 id="文件与终端" tabindex="-1">文件与终端 <a class="header-anchor" href="#文件与终端" aria-label="Permalink to &quot;文件与终端&quot;">​</a></h3><p>文件管理提供了可视化的上传、下载与编辑；终端则可以直接在浏览器里操作服务器，临时改个配置很方便。</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/202407091549709.png" alt="文件管理"></p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/202407091551232.png" alt="终端"></p><h2 id="六、1pctl-命令行工具" tabindex="-1">六、1pctl 命令行工具 <a class="header-anchor" href="#六、1pctl-命令行工具" aria-label="Permalink to &quot;六、1pctl 命令行工具&quot;">​</a></h2><p>面板之外，1Panel 还提供了 <code>1pctl</code> 方便在 SSH 里操作。先看它支持哪些子命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">1pctl</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> --help</span></span></code></pre></div><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/202407091552926.png" alt="1pctl --help"></p><p>忘记登录入口和账号时，用这条命令找回：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">1pctl</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> user-info</span></span></code></pre></div><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/202407091553152.png" alt="1pctl user-info"></p><h2 id="七、小结" tabindex="-1">七、小结 <a class="header-anchor" href="#七、小结" aria-label="Permalink to &quot;七、小结&quot;">​</a></h2><p>1Panel 的上手成本很低，安装脚本把 Docker、服务注册和启动都处理好了，剩下的就是按需点选。对不想在命令行里反复查文档的人来说，它是一个顺手的补充。</p><p>更多细节可以翻阅 <a href="https://1panel.cn/docs/" target="_blank" rel="noreferrer">1Panel 官方文档</a>。</p>`,58)])])}const g=a(p,[["render",l]]);export{k as __pageData,g as default};
